# -*- coding: utf-8 -*-
# DEMO (u) (verified): a layered ("Sommerfeld-type") Green's function is GENERATED by one
# sparse FEM-Kelvin solve -- no Sommerfeld integral, no special functions, no branch cuts.
#
# This is the CONSTRUCTIVE side of act5_01_exterior_material. act5_01_exterior_material showed FEM-Kelvin AVOIDS needing the layered
# Green's function; here we show that if you DO want it, the FEM-Kelvin matrix IS a cheap
# numerical generator of its ACTION. The discrete inverse A^{-1} of the (sparse, SPD) Kelvin-FEM
# operator is the discrete Green's OPERATOR of the layered exterior: apply it to a source ->
# get the field everywhere, including the far field (by the inverse Kelvin map). So the field of a
# source radiating through a stratified medium -- the thing a BEM would obtain by integrating the
# (expensive) Sommerfeld/layered-media Green's function -- here costs ONE sparse solve, with the
# stratification carried as an ordinary FE coefficient and infinity baked in by the Kelvin centre.
#
# Source model: a Dirichlet datum u=Y_n on a body surface r=a is an equivalent surface source
# (single+double layer); the resulting decaying field IS the layered Green's operator applied to
# that boundary source. (A free single-layer with only a one-vertex gauge blows the constant mode
# up ~1e5x -- a Dirichlet body surface is the well-posed way to inject the source.)
#
# Test problem (spherically layered, analytically solvable -> a clean stand-in for the planar
# Sommerfeld case): body r=a, shell mu_s in [b,c], vacuum elsewhere, decaying at infinity:
#     mu(r) = 1     (a < r < b)        vacuum
#             mu_s  (b < r < c)        magnetic shell  (the stratification)
#             1     (c < r < inf)      vacuum, decaying
# Exact layered field R_n(r)=A r^n+B r^{-(n+1)} piecewise, fixed by the 5x5 transfer system
# (Dirichlet at a, mu-continuity at b,c, decay at infinity). FEM-Kelvin must reproduce R_n(r) at
# ALL radii, including the far field read back through the offset Kelvin ball.
#
# Honesty (no overclaim): what is cheap is the OPERATOR/ACTION (one sparse SPD solve) and any
# single value; the FULL dense kernel (all source-observer pairs) is still O(N^2) entries
# (== act4_04_sparse_factorization_of_kernel: the dense BEM kernel is the Schur complement of this very matrix) -- Kelvin-FEM
# makes each entry cheap (sparse solve, no special functions), not the object smaller. Accuracy
# is the FE order x surface reach (the spectral peel-off datasheet). The genuinely HARD Sommerfeld
# case is PLANAR stratification (half-space): under inversion the flat interfaces become spheres
# through the inversion centre -- representable but geometrically heavier (Sugahara's extended
# Kelvin / radiating regime). Here we use spherical layers to keep an exact reference.
import os
os.environ.setdefault("PYTHONIOENCODING", "utf-8")
import time
import numpy as np
import ngsolve as ng
import netgen.occ as occ
from netgen.occ import Sphere, Pnt, Vec, IdentificationType, OCCGeometry
from radia_mcp.radia_ngsolve.fem_bem_coupling import _solid_harmonic

a, b, c, R_out, offset = 0.5, 0.7, 0.9, 1.0, 3.0


def analytic_layered_profile(n, mu_s, r_query):
    """Exact piecewise radial part R_n(r), Dirichlet R_n(a)=1, decay at infinity.
    Unknowns [A1,B1 (a<r<b), A2,B2 (b<r<c, mu_s), b3 (c<r<inf)]."""
    M = np.zeros((5, 5)); rhs = np.zeros(5)
    M[0, 0] = a**n; M[0, 1] = a**-(n + 1); rhs[0] = 1.0                      # u(a)=1
    M[1, 0] = b**n; M[1, 1] = b**-(n + 1); M[1, 2] = -b**n; M[1, 3] = -b**-(n + 1)   # cont @ b
    M[2, 0] = n * b**(n - 1); M[2, 1] = -(n + 1) * b**-(n + 2)               # flux @ b
    M[2, 2] = -mu_s * n * b**(n - 1); M[2, 3] = -mu_s * (-(n + 1)) * b**-(n + 2)
    M[3, 2] = c**n; M[3, 3] = c**-(n + 1); M[3, 4] = -c**-(n + 1)            # cont @ c
    M[4, 2] = mu_s * n * c**(n - 1); M[4, 3] = mu_s * (-(n + 1)) * c**-(n + 2)   # flux @ c
    M[4, 4] = -(-(n + 1)) * c**-(n + 2)
    A1, B1, A2, B2, b3 = np.linalg.solve(M, rhs)

    def Rn(r):
        if r < b:   return A1 * r**n + B1 * r**-(n + 1)
        if r < c:   return A2 * r**n + B2 * r**-(n + 1)
        return b3 * r**-(n + 1)
    return np.array([Rn(r) for r in r_query]), (A1, B1, A2, B2, b3)


# --- self-check: mu_s=1 must reduce to the bare infinite-domain harmonic (a/r)^(n+1) ----------
for n in (1, 2):
    R, (A1, B1, A2, B2, b3) = analytic_layered_profile(n, 1.0, [a, 2 * a])
    assert abs(A1) < 1e-12 and abs(b3 - a**(n + 1)) < 1e-12 and abs(R[1] - 0.5**(n + 1)) < 1e-12, \
        f"infinite-domain self-check failed n={n}: A1={A1}, b3={b3}"
print("self-check OK: mu_s=1 -> bare infinite-domain harmonic (a/r)^(n+1)  (A1=0, b3=a^(n+1))")


def build_mesh(maxh=0.16, order=3):
    inner = Sphere(Pnt(0, 0, 0), a)
    s_b = Sphere(Pnt(0, 0, 0), b); s_c = Sphere(Pnt(0, 0, 0), c)
    outer = Sphere(Pnt(0, 0, 0), R_out)
    for f in inner.faces: f.name = "inner"
    for f in outer.faces: f.name = "kelvin_int"
    sh1 = (s_b - inner); sh1.mat("vac1")
    shm = (s_c - s_b); shm.mat("shell")
    sh3 = (outer - s_c); sh3.mat("vac3")
    kball = Sphere(Pnt(offset, 0, 0), R_out)
    for f in kball.faces: f.name = "kelvin_ext"
    kball.mat("kelvin")
    gnd = occ.Vertex(Pnt(offset, 0, 0)); gnd.name = "GND"
    fi = [f for f in sh3.faces if f.name == "kelvin_int"][0]
    fe = [f for f in kball.faces if f.name == "kelvin_ext"][0]
    fi.Identify(fe, "kelvin", IdentificationType.PERIODIC, occ.gp_Trsf.Translation(Vec(offset, 0, 0)))
    geo = OCCGeometry(occ.Glue([sh1, shm, sh3, kball, gnd]))
    return ng.Mesh(geo.GenerateMesh(maxh=maxh)).Curve(min(order + 1, 4))


def fem_layered_green(n, mu_s, order=3, intorder=10, maxh=0.16):
    mesh = build_mesh(maxh=maxh, order=order)
    x, y, z = ng.x, ng.y, ng.z
    rp2 = (x - offset)**2 + y**2 + z**2 + 1e-20
    mu = mesh.MaterialCF({"vac1": 1.0, "shell": mu_s, "vac3": 1.0,
                          "kelvin": R_out**2 / rp2}, default=1.0)
    fes = ng.Periodic(ng.H1(mesh, order=order, dirichlet="inner|GND"))
    u, v = fes.TnT()
    t0 = time.time()
    A = ng.BilinearForm(mu * ng.grad(u) * ng.grad(v) * ng.dx(bonus_intorder=intorder)); A.Assemble()
    t_asm = time.time() - t0
    gf = ng.GridFunction(fes)
    gf.Set(_solid_harmonic(n) / a**n, ng.BND, definedon=mesh.Boundaries("inner"))   # source = Y_n on body
    rr = gf.vec.CreateVector(); rr.data = -(A.mat * gf.vec)
    t0 = time.time()
    gf.vec.data += A.mat.Inverse(fes.FreeDofs(), inverse="sparsecholesky") * rr
    t_solve = time.time() - t0
    nse = A.mat.AsVector().size; ndof = fes.ndof
    return mesh, gf, dict(ndof=ndof, nnz=nse, fill=nse / float(ndof * ndof),
                          nnz_row=nse / ndof, t_asm=t_asm, t_solve=t_solve)


def sample_axis(mesh, gf, r):
    """field on +z axis at radius r; r>R_out via inverse Kelvin into the offset ball.
    Periodic-glue convention: the scalar potential is CONTINUOUS across Gamma (the Periodic
    space forces u'=u there), so the physical exterior potential equals the ball value at the
    inverted point x'=(offset, 0, R_out^2/r) WITHOUT any (R/rho) weight. (That weight is the
    act3_05_exterior_field_recovery standalone-ball convention, where the *transformed* field is stored instead.)"""
    if r <= R_out - 1e-6:
        return gf(mesh(0, 0, r))
    bp = (offset, 0.0, R_out**2 / r)            # inverse Kelvin: ball-local radius R_out^2/r
    return gf(mesh(*bp))


radii = [0.60, 0.80, 0.96, 1.5, 3.0, 10.0]                 # vac1, shell, vac3(phys), far(Kelvin)
labels = ["a<r<b", "shell", "c<r<R", "FAR", "FAR", "FAR"]

print("\nlayered (Sommerfeld-type) Green's function: ONE Kelvin-FEM solve vs analytic transfer matrix")
print("(source Y_n on body r=%.2f; shell mu_s in [%.2f,%.2f]; exterior r>%.1f via Kelvin ball)" % (a, b, c, R_out))
for n in (1, 2):
    for mu_s in (1.0, 10.0, 50.0):
        mesh, gf, st = fem_layered_green(n, mu_s)
        Yax = float(_solid_harmonic(n)(mesh(0, 0, R_out)))         # angular value on +z axis
        an_R, _ = analytic_layered_profile(n, mu_s, radii)
        an_axis = an_R * Yax
        fem_axis = np.array([sample_axis(mesh, gf, r) for r in radii])
        scale = np.max(np.abs(an_axis)) + 1e-300
        rel = np.abs(fem_axis - an_axis) / scale
        print("\n n=%d  mu_s=%4.1f   ndof=%d  nnz/row=%.1f  fill=%.2f%%  asm=%.2fs  solve=%.2fs"
              % (n, mu_s, st["ndof"], st["nnz_row"], 100 * st["fill"], st["t_asm"], st["t_solve"]))
        print("   r       region     FEM-Kelvin       analytic-layered    rel(/max)")
        for r, lab, fe_, an_ in zip(radii, labels, fem_axis, an_axis):
            print("  %5.2f  %-7s  %15.6e  %16.6e   %.2e" % (r, lab, fe_, an_, abs(fe_ - an_) / scale))
        print("   -> max rel err over all regions (incl. far field via inverse Kelvin): %.2e" % rel.max())

print("\n=> the stratified Green's function's ACTION is one sparse SPD solve (~%.0f nnz/row, fill<0.1%%):" % st["nnz_row"])
print("   no Sommerfeld integral, no special functions, no branch cuts / surface-wave poles, no")
print("   singular quadrature; the shell rides as an FE coefficient and infinity is the Kelvin centre.")
print("   (The full dense kernel is still O(N^2) entries = the Schur complement of this matrix, act4_04_sparse_factorization_of_kernel")
print("    -- Kelvin-FEM makes each entry cheap, it does not make the object smaller.)")
